pub fn parser_state_param(
    params: Rc<Vec<Rc<Node>>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<ParserStateParam>> {
    Rc::new(
        params
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (i as i64, v))
            .collect::<Vec<_>>(),
    )
    .iter()
    .cloned()
    .fold(None, |acc: _, pair: (i64, Rc<Node>)| {
        if (acc.clone() != None) {
            acc.clone()
        } else {
            {
                let idx = pair.0.clone();
                let param = pair.1.clone();
                if (authored_name_at(si.clone(), param_node_type_expr(param.clone()))
                    == "ParserState".to_string())
                {
                    Some(Rc::new(ParserStateParam {
                        name: param_node_name_at(param.clone(), si.clone()),
                        index: idx.clone(),
                    }))
                } else {
                    None
                }
            }
        }
    })
}

pub fn parser_state_base_var(
    expr: Rc<Node>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<String> {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprFieldAccess { .. } => match expr.children.clone().first().cloned() {
            Some(base) => match (*base.expr_data.clone()).clone() {
                ExprData::ExprVar {
                    binding_kind: _, ..
                } => Some(expr_var_name_at(base.clone(), si)),
                _ => None,
            },
            None => None,
        },
        _ => None,
    }
}

pub fn parser_result_state_progress(
    source: Rc<ParserResultSource>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    result_name: String,
) -> DescentEvidence {
    match (*source).clone() {
        ParserResultSource::ParserResultAdvance { input, .. } => {
            strict_after_parser_witness(input.clone())
        }
        ParserResultSource::ParserResultExpect { input, .. } => {
            strict_after_parser_witness(input.clone())
        }
        ParserResultSource::ParserResultEat { input, .. } => {
            if set_has(consumed_true_set, result_name) {
                strict_after_parser_witness(input.clone())
            } else {
                input.clone()
            }
        }
        ParserResultSource::ParserResultCall { input, callee, .. } => {
            if (set_has(consumed_true_set, result_name)
                || set_has(parser_always_advancing, callee.clone()))
            {
                strict_after_parser_witness(input.clone())
            } else {
                input.clone()
            }
        }
        ParserResultSource::ParserResultDirectState { input: p, .. } => p.clone(),
        ParserResultSource::ParserResultOpaque => DescentEvidence::DescentUnknown,
    }
}

pub fn parser_state_arg_expr(
    call_node: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    Rc::new(
        call_node
            .children
            .clone()
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (i as i64, v))
            .collect::<Vec<_>>(),
    )
    .iter()
    .cloned()
    .fold(None, |acc: _, pair: (i64, Rc<Node>)| {
        if (acc.clone() != None) {
            acc.clone()
        } else {
            {
                let idx = pair.0.clone();
                let arg_node = pair.1.clone();
                let matches_state = if (arg_name_at(arg_node.clone(), si.clone()).as_deref()
                    != Some("".to_string()).as_deref())
                {
                    (arg_name_at(arg_node.clone(), si.clone()).as_deref()
                        == Some(state_param.name.clone()).as_deref())
                } else {
                    (idx.clone() == state_param.index.clone())
                };
                if matches_state.clone() {
                    Some(arg_value(arg_node.clone()))
                } else {
                    None
                }
            }
        }
    })
}

pub fn parser_state_expr_progress(
    expr: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> DescentEvidence {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprVar {
                binding_kind: _, ..
            } => {
                let name = expr_var_name_at(expr.clone(), si.clone());
                if (name.clone() == state_param.name.clone()) {
                    DescentEvidence::NonIncreasing
                } else {
                    match v1_rt::map_get(&env.state_aliases.clone(), name.clone()) {
                        Some(progress) => progress.clone(),
                        None => DescentEvidence::DescentUnknown,
                    }
                }
            }
            ExprData::ExprFieldAccess { .. } => {
                if (field_access_field_at(expr.clone(), si.clone()) == "state".to_string()) {
                    match parser_state_base_var(expr.clone(), si.clone()) {
                        Some(result_name) => {
                            match v1_rt::map_get(&env.result_sources.clone(), result_name.clone()) {
                                Some(source) => parser_result_state_progress(
                                    source.clone(),
                                    parser_always_advancing.clone(),
                                    consumed_true_set.clone(),
                                    result_name.clone(),
                                ),
                                None => DescentEvidence::DescentUnknown,
                            }
                        }
                        None => DescentEvidence::DescentUnknown,
                    }
                } else {
                    DescentEvidence::DescentUnknown
                }
            }
            ExprData::ExprCall { .. } => {
                match parser_passthrough_state_expr(expr.clone(), si.clone()) {
                    Some(state_expr) => parser_state_expr_progress(
                        state_expr.clone(),
                        state_param.clone(),
                        env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                }
            }
            ExprData::ExprIf => {
                let cond = if_condition(expr.clone());
                let then_consumed = match parser_progress_flag_var(cond, si.clone()) {
                    Some(name) => {
                        v1_rt::rc_map_insert(consumed_true_set.clone(), name.clone(), true)
                    }
                    None => consumed_true_set.clone(),
                };
                let then_progress = parser_state_expr_progress(
                    if_then_branch(expr.clone()),
                    state_param.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    then_consumed,
                    si.clone(),
                );
                let else_progress = match if_else_branch(expr.clone()) {
                    Some(eb) => parser_state_expr_progress(
                        eb.clone(),
                        state_param.clone(),
                        env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                };
                descent_evidence_lattice_meet(then_progress, else_progress)
            }
            ExprData::ExprLet => {
                let next_env = parser_env_with_binding(
                    let_binding_name_at(expr.clone(), si.clone()),
                    let_value(expr.clone()),
                    env.clone(),
                    state_param.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                match let_body(expr.clone()) {
                    Some(body) => parser_state_expr_progress(
                        body.clone(),
                        state_param.clone(),
                        next_env,
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                }
            }
            ExprData::ExprMatch => {
                let arm_progresses = Rc::new({
                    let mut __result = Vec::new();
                    for arm_node in match_arm_nodes(expr.clone()).iter().cloned() {
                        __result.push(parser_state_expr_progress(
                            arm_body(arm_node.clone()),
                            state_param.clone(),
                            env.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        ));
                    }
                    __result
                });
                match arm_progresses.clone().first().cloned() {
                    Some(initial) => arm_progresses.clone().iter().cloned().fold(
                        initial.clone(),
                        |acc: DescentEvidence, p: DescentEvidence| {
                            descent_evidence_lattice_meet(acc, p.clone())
                        },
                    ),
                    None => DescentEvidence::DescentUnknown,
                }
            }
            ExprData::ExprBlock => parser_block_state_progress(
                expr.children.clone(),
                state_param.clone(),
                env.clone(),
                parser_always_advancing.clone(),
                consumed_true_set.clone(),
                si.clone(),
            ),
            _ => DescentEvidence::DescentUnknown,
        }
    })
}

pub fn parser_block_state_progress(
    stmts: Rc<Vec<Rc<Node>>>,
    state_param: Rc<ParserStateParam>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> DescentEvidence {
    match stmts.clone().last().cloned() {
        None => DescentEvidence::DescentUnknown,
        Some(last_stmt) => {
            let leading = Rc::new(
                stmts
                    .clone()
                    .iter()
                    .cloned()
                    .take(((stmts.clone().len() as i64) - 1) as usize)
                    .collect::<Vec<_>>(),
            );
            let final_env = leading.iter().cloned().fold(
                env.clone(),
                |acc_env: Rc<ParserProgressEnv>, stmt: Rc<Node>| match (*stmt.expr_data.clone())
                    .clone()
                {
                    ExprData::ExprLet => match let_body(stmt.clone()) {
                        None => parser_env_with_binding(
                            let_binding_name_at(stmt.clone(), si.clone()),
                            let_value(stmt.clone()),
                            acc_env.clone(),
                            state_param.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        ),
                        Some(_) => acc_env.clone(),
                    },
                    _ => acc_env.clone(),
                },
            );
            parser_state_expr_progress(
                last_stmt.clone(),
                state_param.clone(),
                final_env,
                parser_always_advancing.clone(),
                consumed_true_set.clone(),
                si.clone(),
            )
        }
    }
}

pub fn parser_result_source_for_expr(
    expr: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<ParserResultSource> {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprCall { .. } => {
            let input_progress =
                match parser_state_arg_expr(expr.clone(), state_param.clone(), si.clone()) {
                    Some(state_expr) => parser_state_expr_progress(
                        state_expr.clone(),
                        state_param.clone(),
                        env,
                        parser_always_advancing,
                        consumed_true_set,
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                };
            match (*parser_result_witness(expr.clone(), si.clone())).clone() {
                ParserResultWitness::ParserWitnessAdvance => {
                    Rc::new(ParserResultSource::ParserResultAdvance {
                        input: input_progress.clone(),
                    })
                }
                ParserResultWitness::ParserWitnessExpect => {
                    Rc::new(ParserResultSource::ParserResultExpect {
                        input: input_progress.clone(),
                    })
                }
                ParserResultWitness::ParserWitnessEat => {
                    Rc::new(ParserResultSource::ParserResultEat {
                        input: input_progress.clone(),
                    })
                }
                ParserResultWitness::ParserWitnessCall { callee: callee, .. } => {
                    match (*callee.clone()).clone() {
                        ParserCallIdentity::ParserCallHelper { helper: _, .. } => {
                            Rc::new(ParserResultSource::ParserResultOpaque)
                        }
                        ParserCallIdentity::ParserCallFunction { name: name, .. } => {
                            match input_progress.clone() {
                                DescentEvidence::DescentUnknown => {
                                    Rc::new(ParserResultSource::ParserResultOpaque)
                                }
                                _ => Rc::new(ParserResultSource::ParserResultCall {
                                    input: input_progress.clone(),
                                    callee: name.clone(),
                                }),
                            }
                        }
                    }
                }
                ParserResultWitness::ParserWitnessOpaque => {
                    Rc::new(ParserResultSource::ParserResultOpaque)
                }
            }
        }
        _ => {
            let progress = parser_success_progress(
                expr.clone(),
                state_param.clone(),
                env,
                parser_always_advancing,
                consumed_true_set,
                si.clone(),
            );
            match progress.clone() {
                DescentEvidence::DescentUnknown => Rc::new(ParserResultSource::ParserResultOpaque),
                _ => Rc::new(ParserResultSource::ParserResultDirectState {
                    input: progress.clone(),
                }),
            }
        }
    }
}

pub fn parser_env_with_binding(
    name: String,
    value_expr: Rc<Node>,
    env: Rc<ParserProgressEnv>,
    state_param: Rc<ParserStateParam>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<ParserProgressEnv> {
    {
        let state_progress = parser_state_expr_progress(
            value_expr.clone(),
            state_param.clone(),
            env.clone(),
            parser_always_advancing.clone(),
            consumed_true_set.clone(),
            si.clone(),
        );
        let result_source = parser_result_source_for_expr(
            value_expr.clone(),
            state_param.clone(),
            env.clone(),
            parser_always_advancing.clone(),
            consumed_true_set.clone(),
            si.clone(),
        );
        Rc::new(ParserProgressEnv {
            state_aliases: v1_rt::rc_map_insert(
                env.state_aliases.clone(),
                name.clone(),
                state_progress,
            ),
            result_sources: v1_rt::rc_map_insert(
                env.result_sources.clone(),
                name.clone(),
                result_source,
            ),
        })
    }
}

pub fn parser_call_edge_progress(
    call_node: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> DescentEvidence {
    match parser_state_arg_expr(call_node.clone(), state_param.clone(), si.clone()) {
        Some(state_expr) => {
            let input_progress = parser_state_expr_progress(
                state_expr.clone(),
                state_param.clone(),
                env,
                parser_always_advancing.clone(),
                consumed_true_set,
                si.clone(),
            );
            if set_has(
                parser_always_advancing.clone(),
                expr_call_func_at(call_node.clone(), si.clone()),
            ) {
                strict_after_parser_witness(input_progress)
            } else {
                input_progress
            }
        }
        None => DescentEvidence::DescentUnknown,
    }
}

pub fn collect_parser_progress_block_edges(
    caller: String,
    stmts: Rc<Vec<Rc<Node>>>,
    state_param: Rc<ParserStateParam>,
    scc_name_set: Rc<HashMap<String, bool>>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<ParserProgressEdge>>> {
    {
        let acc = stmts.iter().cloned().fold(
            Rc::new(ParserProgressAcc {
                edges: Rc::new(vec![]),
                env: env,
            }),
            |acc: Rc<ParserProgressAcc>, stmt: Rc<Node>| match (*stmt.expr_data.clone()).clone() {
                ExprData::ExprLet => match let_body(stmt.clone()) {
                    None => {
                        let value_expr = let_value(stmt.clone());
                        let value_edges = collect_parser_progress_edges(
                            caller.clone(),
                            value_expr.clone(),
                            state_param.clone(),
                            scc_name_set.clone(),
                            acc.env.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        );
                        let next_env = parser_env_with_binding(
                            let_binding_name_at(stmt.clone(), si.clone()),
                            value_expr.clone(),
                            acc.env.clone(),
                            state_param.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        );
                        Rc::new(ParserProgressAcc {
                            edges: v1_rt::concat(acc.edges.clone(), value_edges.clone()),
                            env: next_env.clone(),
                        })
                    }
                    Some(_) => {
                        let stmt_edges = collect_parser_progress_edges(
                            caller.clone(),
                            stmt.clone(),
                            state_param.clone(),
                            scc_name_set.clone(),
                            acc.env.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        );
                        Rc::new(ParserProgressAcc {
                            edges: v1_rt::concat(acc.edges.clone(), stmt_edges.clone()),
                            env: acc.env.clone(),
                        })
                    }
                },
                _ => {
                    let stmt_edges = collect_parser_progress_edges(
                        caller.clone(),
                        stmt.clone(),
                        state_param.clone(),
                        scc_name_set.clone(),
                        acc.env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    );
                    Rc::new(ParserProgressAcc {
                        edges: v1_rt::concat(acc.edges.clone(), stmt_edges.clone()),
                        env: acc.env.clone(),
                    })
                }
            },
        );
        acc.edges.clone()
    }
}

pub fn collect_parser_progress_edges(
    caller: String,
    body: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    scc_name_set: Rc<HashMap<String, bool>>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<ParserProgressEdge>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let own_edges = if set_has(
                    scc_name_set.clone(),
                    expr_call_func_at(body.clone(), si.clone()),
                ) {
                    Rc::new(vec![Rc::new(ParserProgressEdge {
                        caller: caller.clone(),
                        callee: expr_call_func_at(body.clone(), si.clone()),
                        progress: parser_call_edge_progress(
                            body.clone(),
                            state_param.clone(),
                            env.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        ),
                    })])
                } else {
                    Rc::new(vec![])
                };
                let child_edges = Rc::new({
                    let mut __result = Vec::new();
                    for child in body.children.clone().iter().cloned() {
                        __result.extend(
                            (*collect_parser_progress_edges(
                                caller.clone(),
                                child.clone(),
                                state_param.clone(),
                                scc_name_set.clone(),
                                env.clone(),
                                parser_always_advancing.clone(),
                                consumed_true_set.clone(),
                                si.clone(),
                            ))
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                });
                v1_rt::concat(own_edges, child_edges)
            }
            ExprData::ExprIf => {
                let cond = if_condition(body.clone());
                let cond_edges = collect_parser_progress_edges(
                    caller.clone(),
                    cond.clone(),
                    state_param.clone(),
                    scc_name_set.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                let then_consumed = match parser_progress_flag_var(cond.clone(), si.clone()) {
                    Some(name) => {
                        v1_rt::rc_map_insert(consumed_true_set.clone(), name.clone(), true)
                    }
                    None => consumed_true_set.clone(),
                };
                let then_edges = collect_parser_progress_edges(
                    caller.clone(),
                    if_then_branch(body.clone()),
                    state_param.clone(),
                    scc_name_set.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    then_consumed,
                    si.clone(),
                );
                let else_edges = match if_else_branch(body.clone()) {
                    Some(eb) => collect_parser_progress_edges(
                        caller.clone(),
                        eb.clone(),
                        state_param.clone(),
                        scc_name_set.clone(),
                        env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => Rc::new(vec![]),
                };
                v1_rt::concat(v1_rt::concat(cond_edges, then_edges), else_edges)
            }
            ExprData::ExprLet => {
                let value_expr = let_value(body.clone());
                let value_edges = collect_parser_progress_edges(
                    caller.clone(),
                    value_expr.clone(),
                    state_param.clone(),
                    scc_name_set.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                let next_env = parser_env_with_binding(
                    let_binding_name_at(body.clone(), si.clone()),
                    value_expr.clone(),
                    env.clone(),
                    state_param.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                let body_edges = match let_body(body.clone()) {
                    Some(b) => collect_parser_progress_edges(
                        caller.clone(),
                        b.clone(),
                        state_param.clone(),
                        scc_name_set.clone(),
                        next_env,
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => Rc::new(vec![]),
                };
                v1_rt::concat(value_edges, body_edges)
            }
            ExprData::ExprBlock => collect_parser_progress_block_edges(
                caller.clone(),
                body.children.clone(),
                state_param.clone(),
                scc_name_set.clone(),
                env.clone(),
                parser_always_advancing.clone(),
                consumed_true_set.clone(),
                si.clone(),
            ),
            ExprData::ExprMatch => {
                let scrut_edges = collect_parser_progress_edges(
                    caller.clone(),
                    match_scrutinee(body.clone()),
                    state_param.clone(),
                    scc_name_set.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                let arm_edges = Rc::new({
                    let mut __result = Vec::new();
                    for arm_node in match_arm_nodes(body.clone()).iter().cloned() {
                        __result.extend(
                            (*collect_parser_progress_edges(
                                caller.clone(),
                                arm_body(arm_node.clone()),
                                state_param.clone(),
                                scc_name_set.clone(),
                                env.clone(),
                                parser_always_advancing.clone(),
                                consumed_true_set.clone(),
                                si.clone(),
                            ))
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                });
                v1_rt::concat(scrut_edges, arm_edges)
            }
            _ => Rc::new({
                let mut __result = Vec::new();
                for child in body.children.clone().iter().cloned() {
                    __result.extend(
                        (*collect_parser_progress_edges(
                            caller.clone(),
                            child.clone(),
                            state_param.clone(),
                            scc_name_set.clone(),
                            env.clone(),
                            parser_always_advancing.clone(),
                            consumed_true_set.clone(),
                            si.clone(),
                        ))
                        .iter()
                        .cloned(),
                    );
                }
                __result
            }),
        }
    })
}

pub fn parser_record_field_value(
    expr: Rc<Node>,
    field_name: String,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    Rc::new({
        let mut __result = Vec::new();
        for child in Rc::new({
            let mut __result = Vec::new();
            for child in expr.children.clone().iter().cloned() {
                if (field_init_node_name_at(child.clone(), si.clone()) == field_name.clone()) {
                    __result.push(child);
                }
            }
            __result
        })
        .iter()
        .cloned()
        {
            __result.push(field_init_node_value(child.clone()));
        }
        __result
    })
    .first()
    .cloned()
}

pub fn parser_expr_is_none(expr: Rc<Node>) -> bool {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprLiteral { value: v, .. } => match (*v.clone()).clone() {
            LiteralValue::LitNull => true,
            _ => false,
        },
        _ => false,
    }
}

pub fn parser_success_progress(
    expr: Rc<Node>,
    state_param: Rc<ParserStateParam>,
    env: Rc<ParserProgressEnv>,
    parser_always_advancing: Rc<HashMap<String, bool>>,
    consumed_true_set: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> DescentEvidence {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprReturn => parser_success_progress(
                return_value(expr.clone()),
                state_param.clone(),
                env.clone(),
                parser_always_advancing.clone(),
                consumed_true_set.clone(),
                si.clone(),
            ),
            ExprData::ExprVar {
                binding_kind: _, ..
            } => match v1_rt::map_get(
                &env.result_sources.clone(),
                expr_var_name_at(expr.clone(), si.clone()),
            ) {
                Some(source) => parser_result_state_progress(
                    source.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    expr_var_name_at(expr.clone(), si.clone()),
                ),
                None => DescentEvidence::DescentUnknown,
            },
            ExprData::ExprCall { .. } => parser_result_state_progress(
                parser_result_source_for_expr(
                    expr.clone(),
                    state_param.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                ),
                parser_always_advancing.clone(),
                consumed_true_set.clone(),
                "".to_string(),
            ),
            ExprData::ExprRecordLit { parent_enum: _, .. } => {
                match parser_record_field_value(expr.clone(), "err".to_string(), si.clone()) {
                    Some(err_expr) => {
                        if parser_expr_is_none(err_expr.clone()) {
                            match parser_record_field_value(
                                expr.clone(),
                                "state".to_string(),
                                si.clone(),
                            ) {
                                Some(state_expr) => parser_state_expr_progress(
                                    state_expr.clone(),
                                    state_param.clone(),
                                    env.clone(),
                                    parser_always_advancing.clone(),
                                    consumed_true_set.clone(),
                                    si.clone(),
                                ),
                                None => DescentEvidence::DescentUnknown,
                            }
                        } else {
                            DescentEvidence::DescentUnknown
                        }
                    }
                    None => DescentEvidence::DescentUnknown,
                }
            }
            ExprData::ExprIf => {
                let cond = if_condition(expr.clone());
                let then_consumed = match parser_progress_flag_var(cond, si.clone()) {
                    Some(name) => {
                        v1_rt::rc_map_insert(consumed_true_set.clone(), name.clone(), true)
                    }
                    None => consumed_true_set.clone(),
                };
                let then_progress = parser_success_progress(
                    if_then_branch(expr.clone()),
                    state_param.clone(),
                    env.clone(),
                    parser_always_advancing.clone(),
                    then_consumed,
                    si.clone(),
                );
                let else_progress = match if_else_branch(expr.clone()) {
                    Some(eb) => parser_success_progress(
                        eb.clone(),
                        state_param.clone(),
                        env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                };
                descent_evidence_lattice_meet(then_progress, else_progress)
            }
            ExprData::ExprLet => {
                let next_env = parser_env_with_binding(
                    let_binding_name_at(expr.clone(), si.clone()),
                    let_value(expr.clone()),
                    env.clone(),
                    state_param.clone(),
                    parser_always_advancing.clone(),
                    consumed_true_set.clone(),
                    si.clone(),
                );
                match let_body(expr.clone()) {
                    Some(body) => parser_success_progress(
                        body.clone(),
                        state_param.clone(),
                        next_env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                }
            }
            ExprData::ExprBlock => {
                let prefix = v1_rt::reverse(Rc::new(
                    v1_rt::reverse(expr.children.clone())
                        .iter()
                        .cloned()
                        .skip(1 as usize)
                        .collect::<Vec<_>>(),
                ));
                let acc = prefix.iter().cloned().fold(
                    Rc::new(ParserProgressAcc {
                        edges: Rc::new(vec![]),
                        env: env.clone(),
                    }),
                    |acc: Rc<ParserProgressAcc>, stmt: Rc<Node>| match (*stmt.expr_data.clone())
                        .clone()
                    {
                        ExprData::ExprLet => match let_body(stmt.clone()) {
                            None => {
                                let next_env = parser_env_with_binding(
                                    let_binding_name_at(stmt.clone(), si.clone()),
                                    let_value(stmt.clone()),
                                    acc.env.clone(),
                                    state_param.clone(),
                                    parser_always_advancing.clone(),
                                    consumed_true_set.clone(),
                                    si.clone(),
                                );
                                Rc::new(ParserProgressAcc {
                                    edges: acc.edges.clone(),
                                    env: next_env.clone(),
                                })
                            }
                            Some(_) => acc.clone(),
                        },
                        _ => acc.clone(),
                    },
                );
                match expr.children.clone().last().cloned() {
                    Some(last_stmt) => parser_success_progress(
                        last_stmt.clone(),
                        state_param.clone(),
                        acc.env.clone(),
                        parser_always_advancing.clone(),
                        consumed_true_set.clone(),
                        si.clone(),
                    ),
                    None => DescentEvidence::DescentUnknown,
                }
            }
            _ => DescentEvidence::DescentUnknown,
        }
    })
}

pub fn parser_member_is_always_advancing(
    entry: Rc<FuncEntry>,
    parser_name_set: Rc<HashMap<String, bool>>,
    proven: Rc<HashMap<String, bool>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match parser_state_param(entry.params.clone(), si.clone()) {
        Some(state_param) => {
            let edges = collect_parser_progress_edges(
                entry.name.clone(),
                (*entry.body).clone(),
                state_param.clone(),
                parser_name_set,
                empty_parser_progress_env(),
                proven.clone(),
                v1_rt::rc_empty_map::<String, bool>(),
                si.clone(),
            );
            ({
                let mut __all = true;
                for edge in edges.iter().cloned() {
                    if !((edge.progress.clone() == DescentEvidence::Strict)
                        || ((edge.progress.clone() == DescentEvidence::NonIncreasing)
                            && set_has(proven.clone(), edge.callee.clone())))
                    {
                        __all = false;
                        break;
                    }
                }
                __all
            } && (parser_success_progress(
                (*entry.body).clone(),
                state_param.clone(),
                empty_parser_progress_env(),
                proven.clone(),
                v1_rt::rc_empty_map::<String, bool>(),
                si.clone(),
            ) == DescentEvidence::Strict))
        }
        None => false,
    }
}

pub fn infer_parser_always_advancing_members_worklist(
    mut queue: Rc<Vec<String>>,
    mut func_index: Rc<HashMap<String, Rc<FuncEntry>>>,
    mut parser_name_set: Rc<HashMap<String, bool>>,
    mut reverse_graph: Rc<HashMap<String, Rc<Vec<String>>>>,
    mut proven: Rc<HashMap<String, bool>>,
    mut si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, bool>> {
    loop {
        match queue.clone().first().cloned() {
            Some(name) => {
                let rest = Rc::new(
                    queue
                        .clone()
                        .iter()
                        .cloned()
                        .skip(1 as usize)
                        .collect::<Vec<_>>(),
                );
                if set_has(proven.clone(), name.clone()) {
                    {
                        let __tco_0 = rest;
                        queue = __tco_0;
                        continue;
                    }
                } else {
                    match v1_rt::map_get(&func_index, name.clone()) {
                        Some(entry) => {
                            if parser_member_is_always_advancing(
                                entry.clone(),
                                parser_name_set.clone(),
                                proven.clone(),
                                si.clone(),
                            ) {
                                let callers = match v1_rt::map_get(&reverse_graph, name.clone()) {
                                    Some(members) => members.clone(),
                                    None => Rc::new(vec![]),
                                };
                                {
                                    let __tco_0 = deduplicate(v1_rt::concat(rest, callers));
                                    let __tco_1 = v1_rt::rc_map_insert(proven, name.clone(), true);
                                    queue = __tco_0;
                                    proven = __tco_1;
                                    continue;
                                }
                            } else {
                                {
                                    let __tco_0 = rest;
                                    queue = __tco_0;
                                    continue;
                                }
                            }
                        }
                        None => {
                            let __tco_0 = rest;
                            queue = __tco_0;
                            continue;
                        }
                    }
                }
            }
            None => {
                break proven.clone();
            }
        }
    }
}

pub fn infer_parser_always_advancing_members(
    members: Rc<Vec<String>>,
    func_index: Rc<HashMap<String, Rc<FuncEntry>>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, bool>> {
    {
        let parser_name_set = members.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, bool>(),
            |acc: Rc<HashMap<String, bool>>, name: String| {
                v1_rt::rc_map_insert(acc, name.clone(), true)
            },
        );
        let parser_entries = Rc::new({
            let mut __result = Vec::new();
            for name in members.clone().iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(&func_index, name.clone()) {
                        Some(entry) => Rc::new(vec![entry.clone()]),
                        None => Rc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let call_graph = build_call_graph(parser_entries, si.clone());
        let reverse_graph = reverse_adjacency(members.clone(), call_graph);
        infer_parser_always_advancing_members_worklist(
            members.clone(),
            func_index.clone(),
            parser_name_set,
            reverse_graph,
            v1_rt::rc_empty_map::<String, bool>(),
            si.clone(),
        )
    }
}

pub fn parser_function_names(
    func_index: Rc<HashMap<String, Rc<FuncEntry>>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for name in Rc::new(v1_rt::map_keys(&func_index)).iter().cloned() {
            if match v1_rt::map_get(&func_index, name.clone()) {
                Some(entry) => (parser_state_param(entry.params.clone(), si.clone()) != None),
                None => false,
            } {
                __result.push(name);
            }
        }
        __result
    })
}

pub fn infer_all_parser_always_advancing(
    func_index: Rc<HashMap<String, Rc<FuncEntry>>>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, bool>> {
    {
        let members = parser_function_names(func_index.clone(), si.clone());
        infer_parser_always_advancing_members(members, func_index.clone(), si.clone())
    }
}

