pub fn is_tokens_input_expr(
    mut expr: Rc<Node>,
    mut param_name: String,
    mut vars: Rc<HashMap<String, bool>>,
    mut si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprVar {
                binding_kind: _, ..
            } => {
                let vname = expr_var_name_at(expr.clone(), si.clone());
                break ((vname.clone() == param_name.clone()) || set_has(vars, vname.clone()));
            }
            ExprData::ExprFieldAccess { .. } => {
                let field = field_access_field_at(expr.clone(), si.clone());
                if (field == param_name.clone()) {
                    break true;
                } else {
                    let base = field_access_base(expr.clone());
                    match (*base.expr_data.clone()).clone() {
                        ExprData::ExprVar {
                            binding_kind: _, ..
                        } => {
                            let bname = expr_var_name_at(base.clone(), si.clone());
                            break ((bname.clone() == param_name.clone())
                                || set_has(vars, bname.clone()));
                        }
                        _ => {
                            break false;
                        }
                    }
                }
            }
            ExprData::ExprMethodCall {
                method_semantics: ms,
                ..
            } => match method_size_effect(ms.clone()) {
                Some(CollectionSizeEffect::ShrinkEffect) => {
                    let __tco_0 = method_receiver(expr);
                    expr = __tco_0;
                    continue;
                }
                _ => {
                    break false;
                }
            },
            ExprData::ExprCall { .. } => {
                if is_list_passthrough_call(expr.clone(), si.clone()) {
                    match list_passthrough_inner_arg(expr.clone(), si.clone()) {
                        Some(inner) => {
                            let __tco_0 = inner.clone();
                            expr = __tco_0;
                            continue;
                        }
                        None => {
                            break false;
                        }
                    }
                } else {
                    match consuming_tokens_arg(expr.clone(), si.clone()) {
                        Some(tokens_arg) => {
                            let __tco_0 = tokens_arg.clone();
                            expr = __tco_0;
                            continue;
                        }
                        None => {
                            break false;
                        }
                    }
                }
            }
            _ => {
                break false;
            }
        }
    }
}

